------------------------------------------------------------
-- 1. MONITEURS
-- https://wiki.hypr.land/Configuring/Basics/Monitors/
------------------------------------------------------------

hl.monitor({
	output = "", -- "" = s'applique à tous les moniteurs non configurés explicitement
	mode = "1920x1080@60.Hz",
	position = "auto",
	scale = "1",
})

------------------------------------------------------------
-- 2. PROGRAMMES / COMMANDES PERSONNALISÉES
-- Centralise ici les commandes réutilisées plus bas dans les
-- raccourcis clavier, pour ne les modifier qu'à un seul endroit.
------------------------------------------------------------

local terminal = "kitty"
local fileManager = "nemo"
local browser = "firefox"
local menurun = "rofi -show combi -modes combi -combi-modes 'windows,drun,run' -display-combi ' '"

-- Screenshot d'une zone sélectionnée (grim + slurp), enregistré en JPEG horodaté.
local take_a_screenshot =
	"mkdir -p ~/Images/Screenshots && grim -g \"$(slurp)\" -t jpeg -q 50 ~/Images/Screenshots/$(date +'%Y-%m-%d_%H-%M-%S').jpeg"

-- Redémarre Waybar (utile après un changement de config/CSS).
local reload_waybar = "killall waybar && waybar"

-- Bascule le verrou anti-veille (voir hypridle.conf : condition_cmd
-- vérifie l'existence de ce fichier avant de suspendre la machine).
local toggle_idle_inhibit = os.getenv("HOME") .. "/.config/hypr/scripts/toggle-idle-inhibit.sh"

------------------------------------------------------------
-- 3. AUTOSTART
-- https://wiki.hypr.land/Configuring/Basics/Autostart/
------------------------------------------------------------

hl.on("hyprland.start", function()
	-- hl.exec_cmd(terminal)
	-- hl.exec_cmd("nm-applet")

	hl.exec_cmd("waybar & hyprpaper") -- barre de statut + fond d'écran
	hl.exec_cmd("hypridle") -- gestion de l'inactivité / veille
	hl.exec_cmd("systemctl --user enable --now hyprpolkitagent.service") -- agent d'authentification graphique
	hl.exec_cmd("wl-paste --type text --watch cliphist store") -- historique presse-papiers (texte)
	hl.exec_cmd("wl-paste --type image --watch cliphist store") -- historique presse-papiers (images)
end)

