-- 8. LAYOUTS
------------------------------------------------------------

-- Dwindle — https://wiki.hypr.land/Configuring/Layouts/Dwindle-Layout/
hl.config({
	dwindle = {
		preserve_split = true, -- recommandé
	},
})

-- Master — https://wiki.hypr.land/Configuring/Layouts/Master-Layout/
hl.config({
	master = {
		new_status = "master",
	},
})

-- Scrolling — https://wiki.hypr.land/Configuring/Layouts/Scrolling-Layout/
hl.config({
	scrolling = {
		fullscreen_on_one_column = true,
	},
})

------------------------------------------------------------
-- 9. DIVERS
------------------------------------------------------------

hl.config({
	misc = {
		force_default_wallpaper = 0, -- 0/1 pour désactiver la mascotte animée
		disable_hyprland_logo = false, -- true = désactive le fond d'écran logo/anime aléatoire
	},
})

------------------------------------------------------------
-- 10. INPUT
------------------------------------------------------------

hl.config({
	input = {
		kb_layout = "us",
		kb_variant = "qwerty-fr",
		kb_model = "",
		kb_options = "",
		kb_rules = "",

		follow_mouse = 1,

		touchpad = {
			natural_scroll = true,
			scroll_factor = 0.7,
			disable_while_typing = true,
		},
	},
})

-- Trackpoint (ex. ThinkPad).
-- https://wiki.hypr.land/Configuring/Advanced-and-Cool/Devices/
hl.device({
	name = "tpps/2-elan-trackpoint",
	sensitivity = 0.7,
	accel_profile = "flat",
})

-- Geste 3 doigts horizontal = changement de workspace.
hl.gesture({
	fingers = 3,
	direction = "horizontal",
	action = "workspace",
})

------------------------------------------------------------
-- 11. RACCOURCIS CLAVIER
-- https://wiki.hypr.land/Configuring/Basics/Binds/
------------------------------------------------------------

local mainMod = "SUPER" -- touche "Windows" comme modificateur principal

-- ---- Applications ----

hl.bind(mainMod .. " + return ", hl.dsp.exec_cmd(terminal)) -- ouvrir le terminal
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager)) -- ouvrir le gestionnaire de fichiers
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd(browser)) -- ouvrir le navigateur
hl.bind(mainMod .. " + space", hl.dsp.exec_cmd(menurun)) -- lanceur d'applications (rofi)

-- ---- Fenêtres ----

local closeWindowBind = hl.bind(mainMod .. " + Q", hl.dsp.window.close()) -- fermer la fenêtre active
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" })) -- flottant on/off
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo()) -- mode pseudo (dwindle)
hl.bind(mainMod .. " + O", hl.dsp.layout("togglesplit")) -- inverser le split (dwindle uniquement)
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" })) -- plein écran

-- Déplacer le focus avec mainMod + flèches (HJKL, style Vim)
hl.bind(mainMod .. " + H", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + L", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + K", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + J", hl.dsp.focus({ direction = "down" }))

-- Déplacer/redimensionner une fenêtre avec mainMod + clic gauche/droit + glisser
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- ---- Workspaces ----

-- Basculer vers / déplacer une fenêtre vers un workspace avec mainMod (+ SHIFT) + [0-9]
for i = 1, 10 do
	local key = i % 10 -- 10 correspond à la touche 0
	hl.bind(mainMod .. " + " .. key, hl.dsp.focus({ workspace = i }))
	hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

-- Workspace spécial (scratchpad)
hl.bind(mainMod .. " + S", hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Défiler entre les workspaces avec mainMod + molette
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up", hl.dsp.focus({ workspace = "e-1" }))

-- ---- Système / outils ----

hl.bind(mainMod .. " + SHIFT + W", hl.dsp.exec_cmd(reload_waybar)) -- redémarrer Waybar
hl.bind(mainMod .. " + Print", hl.dsp.exec_cmd(take_a_screenshot)) -- capture d'écran (zone)
hl.bind(mainMod .. " + SHIFT + I", hl.dsp.exec_cmd(toggle_idle_inhibit)) -- bascule anti-veille

hl.bind(
	mainMod .. " + SHIFT + M",
	hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'")
) -- menu d'extinction / déconnexion

hl.bind(
	"XF86PowerOff",
	hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"),
	{ locked = true }
) -- touche dédiée power off (fonctionne même écran verrouillé)

-- ---- Touches multimédias (clavier / portable) ----

hl.bind(
	"XF86AudioRaiseVolume",
	hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"),
	{ locked = true, repeating = true }
)
hl.bind(
	"XF86AudioLowerVolume",
	hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),
	{ locked = true, repeating = true }
)
hl.bind(
	"XF86AudioMute",
	hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),
	{ locked = true, repeating = true }
)
hl.bind(
	"XF86AudioMicMute",
	hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),
	{ locked = true, repeating = true }
)
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"), { locked = true, repeating = true })

-- Nécessite playerctl
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true })

------------------------------------------------------------
-- 12. RÈGLES DE FENÊTRES / CALQUES
-- https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/
------------------------------------------------------------

-- Ignorer les demandes de maximisation de toutes les applis (généralement souhaitable).
local suppressMaximizeRule = hl.window_rule({
	name = "suppress-maximize-events",
	match = { class = ".*" },

	suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

-- Corrige des soucis de drag avec XWayland.
hl.window_rule({
	name = "fix-xwayland-drags",
	match = {
		class = "^$",
		title = "^$",
		xwayland = true,
		float = true,
		fullscreen = false,
		pin = false,
	},

	no_focus = true,
})

-- Les règles de calque (layer_rule) renvoient aussi un handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Fenêtre de hyprland-run : position flottante en bas à gauche.
hl.window_rule({
	name = "move-hyprland-run",
	match = { class = "hyprland-run" },

	move = "20 monitor_h-120",
	float = true,
})
